static int aera_i18n_locale_index(void) {
  const char *locale = getenv("AERA_LOCALE");
  if (!locale || !locale[0]) return 0;
  for (int index = 1; index < 32; ++index) {
    if (!strcmp(locale, aera_i18n_locales[index])) return index;
  }
  return 0;
}

static const char *aera_tr(const char *english) {
  static int locale = -1;
  if (!english || !english[0]) return english;
  if (locale < 0) locale = aera_i18n_locale_index();
  if (!locale) return english;
  for (size_t index = 0;
       index < sizeof(aera_i18n_rows) / sizeof(aera_i18n_rows[0]); ++index) {
    if (!strcmp(english, aera_i18n_rows[index].value[0]))
      return aera_i18n_rows[index].value[locale];
  }
  return english;
}

